typedef unsigned int color32;

struct TextString {
    char padding[0x48];
    color32 color;
};

struct FEMenuEntry {};

struct FEManager {
    char padding[0x15644];
    color32 col_info_b;
    color32 col_info_g;
};

struct menu_slot {
    short adjustment;
    unsigned short reserved;
    void (*function)(void *, FEMenuEntry *, bool);
};

struct menu_vtable {
    char padding[0x18];
    menu_slot set_high;
};

struct menu_base {
    char padding[0x74];
    menu_vtable *vtable;
};

struct system_slot {
    short adjustment;
    unsigned short reserved;
    void (*function)(void *, bool);
};

struct system_vtable {
    char padding[0x58];
    system_slot end_draw;
};

struct GraphicalMenuSystem {
    char padding[0x8c];
    system_vtable *vtable;

    inline void endDraw(bool value)
    {
        system_slot &slot = vtable->end_draw;
        slot.function((char *)this + slot.adjustment, value);
    }
};

struct game {
    char padding[0x228];
    int beach_id;

    inline int get_beach_id() const { return beach_id; }
};

struct SoundScriptManager {
    void unpause();
    void playEvent(int, void * = 0, float = 0.0f);
    void pause();
    static SoundScriptManager *inst();
};

enum {
    NUM_COLUMNS = 5,
    SS_FE_ONX = 24
};

class HighScoreFrontEnd {
    char padding0[0x50];
    GraphicalMenuSystem *system;
    char padding1[0x20];
    menu_vtable *menu_table;
    char padding2[0xc0];
    FEManager *manager;
    char padding3[0x38];
    TextString *info[10][NUM_COLUMNS];
    char padding4[0x48];
    bool in_game;
    char padding5[0x0b];
    FEMenuEntry *all_beaches[44];
    char padding6[0xac];
    int first_line;
    int second_line;

    inline void setHigh(FEMenuEntry *entry, bool value = true)
    {
        menu_slot &slot = menu_table->set_high;
        slot.function((char *)this + 0x80 + slot.adjustment, entry, value);
    }

public:
    void Select(int entry_index);
    void OnSwitchBeach();
};

extern game *g_game_ptr;
extern SoundScriptManager *sound_manager;

__asm__(".equ g_game_ptr, 0x0046AC64");
__asm__(".equ sound_manager, 0x0046B4A0");
__asm__(".equ unpause__18SoundScriptManager, 0x0031BFA8");
__asm__(".equ playEvent__18SoundScriptManager9EventTypeP6entityf, 0x0031C380");
__asm__(".equ pause__18SoundScriptManager, 0x0031BF98");
__asm__(".equ OnSwitchBeach__17HighScoreFrontEnd, 0x001CBAD0");

inline SoundScriptManager *SoundScriptManager::inst()
{
    return sound_manager;
}

void HighScoreFrontEnd::Select(int entry_index)
{
	if(in_game)
	{
		if(first_line != -1)
		{
			// reset the flashing color correctly
			for(int i=0; i<NUM_COLUMNS; i++)
				info[first_line][i]->color = (i==1 || i==3) ? manager->col_info_b : manager->col_info_g;
		}

		if(second_line != -1)
		{
			first_line = second_line;
			second_line = -1;
			setHigh(all_beaches[g_game_ptr->get_beach_id()]);
			OnSwitchBeach();
		}
		else
		{
			//manager->IGO->ShowMenuBackground(true);
			//system->MakeActive(next_menu);
			SoundScriptManager::inst()->unpause();
			SoundScriptManager::inst()->playEvent(SS_FE_ONX);
			SoundScriptManager::inst()->pause();
			system->endDraw(false);
		}
	}
}
